-- What kind of data each declared file holds (the project lead's request and rules, 31 October 2026):
--   a parameter is one value, with its concept and meaning (name, unit, source, where it is used); a file of more than
--   one value is a dataset. Every value that can be changed to make a different run or model behaviour is a parameter
--   or a dataset of coefficients; a coefficient belongs to the scenario (every scenario has its own).
-- A first classification by file and by rule (the basis column says which), to be reviewed.
--   base          dataset: the base year's levels and prices (activity levels, herds, land, prices, balances, trade
--                 flows): redone with a new base year
--   reference     dataset: CAPRI's 2030 levels and prices (its baseline point and path): redone with a new projection
--   coefficients  dataset: coefficients (per ha, per head, per t, shares), elasticities, cost curves, emission and loss
--                 factors, policy instruments and targets: what a scenario or a re-estimation changes
--   calibrated    dataset: coefficients CAPRI derives from the others (PMP terms, curvature matrices, fertiliser
--                 priors, need multipliers, land-market terms): recalibrated whenever the base or the baseline changes
--   parameters    the parameters, one value each with its concept and meaning (codes/model_parameters.csv)
--   structure     codes, sets, correspondences
--   validation    results kept for comparison, read by no model code

CREATE TABLE data_kind (
    file VARCHAR PRIMARY KEY,
    kind VARCHAR NOT NULL CHECK (kind IN ('base', 'reference', 'coefficients', 'calibrated', 'parameters', 'structure', 'validation')),
    basis VARCHAR NOT NULL
);
COMMENT ON TABLE data_kind IS 'the kind of data of every declared file (base, reference, coefficients, calibrated, parameters, structure, validation) and the basis of the classification';

